import{z as l,x as d,o,c as p,q as n,j as i,D as s,d as r,s as t,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"RDMA 在 OS 中的位置","description":"","frontmatter":{"title":"RDMA 在 OS 中的位置","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rdma-os.md","filePath":"cs/rdma-os.md","lastUpdated":1791063341000}'),B={name:"cs/rdma-os.md"};function D(P,a,m,R,M,C){const E=d("Mermaid");return o(),p("div",null,[a[2]||(a[2]=n('<h1 id="rdma-在-os-中的位置" tabindex="-1">RDMA 在 OS 中的位置 <a class="header-anchor" href="#rdma-在-os-中的位置" aria-label="Permalink to &quot;RDMA 在 OS 中的位置&quot;">​</a></h1><div class="epigraph"><p>RDMA 把注册过的用户内存直接交给网卡 DMA，绕过 TCP 与套接字缓冲；内核只做连接、注册与完成队列的映射。</p><footer>—— 据 InfiniBand/RDMA 规范直觉；Linux rdma-core 与 ibverbs 文档；RFC 5040 对 iWARP 的背景</footer></div><p><a href="/cs/zero-copy-network">零拷贝</a> 仍常走 TCP。<a href="/cs/dpdk-kernel-bypass">DPDK</a> 旁路的是整栈。缺口是 <strong>RDMA 在 OS 里的位置</strong>：verbs、MR、QP，以及它不是文件系统的 RDMA 导出百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HPC/存储要微秒级、少拷贝。RDMA：进程注册虚址，卡拿到翻译（或 on-demand paging）；QP 成对，post send/recv 或 RDMA WRITE 不经过对端 CPU。缺口：内核模块（ib_core）管理设备，用户 libibverbs mmap 门铃；与 socket 并行存在，应用要改 API。本课不把 RoCE 拥塞控制写成传输课全文。</p><p><span class="marginnote">直觉类比：注册内存（MR）像给快递员（网卡）办的一张门禁卡——只对你登记过的那几间房（虚址区间）有效，房间里的东西怎么搬都不用你亲手经手（CPU 不碰字节）。QP 则是两栋楼之间拉的一条专用传送带，发送就是把货放上带，完成情况写在门口的完成队列板上。</span></p><p><span class="marginnote">rping 一类工具只为证明路径。NVMe-oF RDMA 把块命令放在这套 QP 上，存储栈与网络在此汇合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>打开设备 → PD → 注册 MR → 建 CQ/QP → 交换 QP 号（TCP 带外）→ post。完成：poll CQ，与 <a href="/cs/nvme-driver">NVMe</a> 同构。对照 TCP：无 sk_buff 数据路径。对照 XDP：XDP 仍以太网；RDMA 是另一种 verbs 设备。</p><p><span class="marginnote">数字实例：一次小消息往返，走内核 TCP 大约几十微秒、数据要经内核缓冲各拷一遍；走 RDMA 通常一两微秒、字节不经过任何 CPU。差出的几十微秒正来自省掉的系统调用、协议处理与两次拷贝——这就是 HPC 与 NVMe-oF 愿意重写 API 的全部理由。</span></p>',10)),(o(),i(A,null,{default:s(()=>[t(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22ibv_post_send%22%5D%20--%3E%20QP%5B%22%E9%98%9F%E5%88%97%E5%AF%B9%22%5D%0A%20%20MR%5B%22%E6%B3%A8%E5%86%8C%E5%86%85%E5%AD%98%22%5D%20--%3E%20NIC%5B%22RNIC%20DMA%22%5D%0A%20%20QP%20--%3E%20NIC%0A%20%20NIC%20--%3E%20CQ%5B%22%E5%AE%8C%E6%88%90%E9%98%9F%E5%88%97%22%5D%0A%20%20CQ%20--%3E%20POLL%5B%22%E7%94%A8%E6%88%B7%20poll%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("OS 把「安全 DMA 窗口」当成一等资源（MR），把网络变成类似块设备的队列。内核不再逐字节解释流。不要写成量化超低延迟撮合。错误：pin 过多内存会伤页回收——"),e("a",{href:"/cs/rmap"},"rmap"),r(" 后课会再遇钉页。")],-1)),a[5]||(a[5]=e("p",null,"与 netns：RDMA 设备的 ns 支持不完整于普通网卡，部署要查清。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「RDMA 绕过内核」等于「完全不需要内核」。数据路径确实不进内核，但控制路径全程在内核：打开设备、建保护域、注册内存、创建 QP、故障恢复。把控制路径也写成用户态轮询，既得不到安全（MR 的授权本来就是内核发的），也救不了错误处理。")],-1)),(o(),i(A,null,{default:s(()=>[t(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E8%BF%9B%E7%A8%8B%E6%B3%A8%E5%86%8C%E8%99%9A%E5%9D%80%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20MR%5B%22%E5%86%85%E6%A0%B8%E5%BB%BA%20MR%EF%BC%9A%E9%92%89%E9%A1%B5%E5%B9%B6%E6%8A%8A%E7%BF%BB%E8%AF%91%E7%BB%99%E7%BD%91%E5%8D%A1%22%5D%0A%20%20MR%20--%3E%20DMA%5B%22RNIC%20%E7%9B%B4%E6%8E%A5%20DMA%20%E8%AF%A5%E5%8C%BA%E9%97%B4%22%5D%0A%20%20APP%20--%3E%20PIN%5B%22%E8%A2%AB%E9%92%89%E7%9A%84%E9%A1%B5%E4%B8%8D%E5%8F%AF%E5%9B%9E%E6%94%B6%22%5D%0A%20%20PIN%20--%3E%20PRESS%5B%22%E9%95%BF%E6%9C%9F%E6%B3%A8%E5%86%8C%E8%BF%87%E5%A4%9A%EF%BC%9A%E5%8F%AF%E8%BF%81%E7%A7%BB%E5%86%85%E5%AD%98%E5%8F%98%E5%B0%91%22%5D%0A%20%20PRESS%20--%3E%20FRAG%5B%22%E9%A1%B5%E5%9B%9E%E6%94%B6%E4%B8%8E%20compaction%20%E5%A4%B1%E8%B4%A5%E9%A3%8E%E9%99%A9%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>实现上：MR 钉页对抗回收，注册过多会让 compaction 失败。QP 状态错误只在 CQ 上看见，应用要把完成当 ABI。RoCE 丢包行为与 InfiniBand 可靠服务不同。 读法上只引用<a href="/cs/zero-copy-network">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>RDMA 在 OS 中的位置</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入全部 QP 状态图。不保证 Soft-RoCE 的性能。网络课序收口于「还有套接字选项这层旋钮」。下一课把 POSIX 套接字选项钉住，作为应用仍走内核 TCP 时的接口。</p><p>版本字段会变，课序钉的是机制对象「RDMA 在 OS 中的位置」，不是某一主线内核的结构体名。 后课默认：RDMA 用 verbs 与注册内存，不经 TCP 数据路径。普通套接字的选项如何改内核行为，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RDMA：内核管注册与 QP，数据 DMA 进用户 MR。</li><li>与 socket/DPDK/XDP 是不同接头。</li><li>套接字选项是下一课。</li><li>出处：rdma-core；InfiniBand 直觉；Linux RDMA。</li></ul>',8))])}const u=l(B,[["render",D]]);export{f as __pageData,u as default};
